from itertools import combinations

g = combinations(range(8), 2)
edges = list(g)

for coloring in range(2**28):
    color_list = [(coloring >> i) & 1 for i in range(28)]

    valid = True

    for i in range(8):
        for j in range(i+1, 8):
            for k in range(j+1, 8):
                idx1 = edges.index((i,j))
                idx2 = edges.index((i,k))
                idx3 = edges.index((j,k))

                if color_list[idx1] == color_list[idx2] == color_list[idx3] == 0:
                    valid = False
                    break

            if not valid:
                break

        if not valid:
            break

    if not valid:
        continue

    for i in range(8):
        for j in range(i+1, 8):
            for k in range(j+1, 8):
