                    if color_list[idx1] == color_list[idx2] == color_list[idx3] == color_list[idx4] == color_list[idx5] == color_list[idx6] == 1:
                        valid = False
                        break

                if not valid:
                    break

            if not valid:
                break

        if not valid:
            break

    if valid:
